const { chromium } = require('playwright');
const path = require('path');

const REPORT = 'file://' + path.resolve(__dirname, 'report.html');
const OUT = __dirname;

(async () => {
  const browser = await chromium.launch({ headless: true });
  const errors = [];

  for (const [slug, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } });
    page.on('pageerror', (e) => errors.push(`${slug} pageerror: ${e.message}`));
    page.on('console', (m) => { if (m.type() === 'error') errors.push(`${slug} console: ${m.text()}`); });
    await page.goto(REPORT, { waitUntil: 'load' });
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth > document.documentElement.clientWidth
    );
    console.log(`${slug} ${width}x${height}: title="${await page.title()}" horizontalScroll=${overflow}`);
    await page.screenshot({ path: `${OUT}/report-${slug}.png`, fullPage: true });
    await page.close();
  }

  await browser.close();
  if (errors.length) { console.log('ERRORS:'); errors.forEach((e) => console.log(' ', e)); process.exit(1); }
  console.log('OK: no page errors');
})();

